package com.loyu3c.rental;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.nio.charset.StandardCharsets;import org.json.JSONObject;
final class SyncSettings {
    private static SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);String alias="rental-google-sync";if(store.containsAlias(alias))return ((KeyStore.SecretKeyEntry)store.getEntry(alias,null)).getSecretKey();KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return generator.generateKey();}
    static void save(Context context,String url,String token)throws Exception{SyncProtocol.endpoint(url);SyncProtocol.token(token);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());byte[] encrypted=cipher.doFinal(new JSONObject().put("url",url).put("token",token).toString().getBytes(StandardCharsets.UTF_8));String value=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(encrypted,Base64.NO_WRAP);if(!context.getSharedPreferences("googleSync",Context.MODE_PRIVATE).edit().clear().putString("connection",value).commit())throw new IllegalStateException("同步設定保存失敗");}
    static JSONObject load(Context context)throws Exception{String value=context.getSharedPreferences("googleSync",Context.MODE_PRIVATE).getString("connection",null);if(value==null)return null;String[] parts=value.split(":");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return new JSONObject(new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8));}
}
